script:
(() => {

const root = root_element;

if (!root) {
    return;
}


/* =====================================================
   EMPLOYEE ELEMENTS
   ===================================================== */

const employeeName =
    root.querySelector(".employee-name");

const employeeDepartment =
    root.querySelector(".employee-department");

const employeeDesignation =
    root.querySelector(".employee-designation");

const employeeId =
    root.querySelector(".employee-id");

const employeeAvatar =
    root.querySelector(".employee-avatar");

const employeeAvatarFallback =
    root.querySelector(".employee-avatar-fallback");

const metaSeparator =
    root.querySelector(".meta-separator");


/* =====================================================
   SUMMARY ELEMENTS
   ===================================================== */

const checkIn =
    root.querySelector("#check-in");

const checkOut =
    root.querySelector("#check-out");

const requiredHours =
    root.querySelector("#required-hours");

const workingHours =
    root.querySelector("#working-hours");

const effectiveHours =
    root.querySelector("#effective-hours");


/* =====================================================
   FORMAT TIME
   ===================================================== */

function formatTime(value) {

if (!value) {
    return "-";
}

try {

    const date = frappe.datetime.str_to_obj(value);

    if (!date) {
        return "-";
    }

    return date.toLocaleTimeString(
        "en-IN",
        {
            hour: "2-digit",
            minute: "2-digit",
            hour12: true
        }
    );

} catch (error) {

    console.error(
        "Time formatting error:",
        error
    );

    return value;
}

}


/* =====================================================
   FORMAT HOURS
   ===================================================== */

function formatHours(value) {

    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {
        return "-";
    }

    const hours = parseFloat(value);

    if (isNaN(hours)) {
        return "-";
    }

    return `${hours.toFixed(2)} hrs`;
}


/* =====================================================
   EMPLOYEE DETAILS
   ===================================================== */

function setEmployeeDetails(details) {

    if (!details) {
        return;
    }

    const department =
        details.department || "";

    const designation =
        details.designation || "";


    if (employeeName) {

        employeeName.textContent =
            details.employee_name || "-";

    }


    if (employeeDepartment) {

        employeeDepartment.textContent =
            department;

    }


    if (employeeDesignation) {

        employeeDesignation.textContent =
            designation;

    }


    if (metaSeparator) {

        metaSeparator.style.display =
            department && designation
                ? "inline"
                : "none";

    }


    if (employeeId) {

        employeeId.textContent =
            details.employee_id || "-";

    }


    if (
        employeeAvatar &&
        details.avatar
    ) {

        employeeAvatar.src =
            details.avatar;

        employeeAvatar.style.display =
            "block";

        if (employeeAvatarFallback) {

            employeeAvatarFallback.style.display =
                "none";

        }

    }

}


/* =====================================================
   SUMMARY DATA
   ===================================================== */

function setData(data) {

    if (!data) {
        return;
    }


    /* Employee */

    setEmployeeDetails(
        data.employee_details
    );


    /* Check In */

    if (checkIn) {

        checkIn.textContent =
            formatTime(
                data.check_in
            );

    }


    /* Check Out */

    if (checkOut) {

        checkOut.textContent =
            formatTime(
                data.check_out
            );

    }


    /* Required Hours */

    if (requiredHours) {

        requiredHours.textContent =
            formatHours(
                data.required_hours
            );

    }


    /* Working Hours

       Calculated from Employee Checkin
       IN / OUT records.
    */

    if (workingHours) {

        workingHours.textContent =
            formatHours(
                data.working_hours
            );

    }


    /* Effective Hours

       Calculated from submitted
       Timesheet Detail hours.
    */

    if (effectiveHours) {

        effectiveHours.textContent =
            formatHours(
                data.effective_hours
            );

    }

}


/* =====================================================
   LOADING STATE
   ===================================================== */

function setLoading() {

    if (employeeName) {
        employeeName.textContent =
            "Loading...";
    }

    if (employeeDepartment) {
        employeeDepartment.textContent =
            "-";
    }

    if (employeeDesignation) {
        employeeDesignation.textContent =
            "-";
    }

    if (employeeId) {
        employeeId.textContent =
            "-";
    }


    if (checkIn) {
        checkIn.textContent =
            "...";
    }

    if (checkOut) {
        checkOut.textContent =
            "...";
    }

    if (requiredHours) {
        requiredHours.textContent =
            "...";
    }

    if (workingHours) {
        workingHours.textContent =
            "...";
    }

    if (effectiveHours) {
        effectiveHours.textContent =
            "...";
    }

}


/* =====================================================
   ERROR STATE
   ===================================================== */

function showError() {

    if (employeeName) {
        employeeName.textContent =
            "Unable to load employee";
    }

    if (employeeDepartment) {
        employeeDepartment.textContent =
            "-";
    }

    if (employeeDesignation) {
        employeeDesignation.textContent =
            "-";
    }

    if (employeeId) {
        employeeId.textContent =
            "-";
    }


    if (checkIn) {
        checkIn.textContent =
            "-";
    }

    if (checkOut) {
        checkOut.textContent =
            "-";
    }

    if (requiredHours) {
        requiredHours.textContent =
            "-";
    }

    if (workingHours) {
        workingHours.textContent =
            "-";
    }

    if (effectiveHours) {
        effectiveHours.textContent =
            "-";
    }

}


/* =====================================================
   LOAD MY DAY SUMMARY
   ===================================================== */

function loadMyDaySummary() {

    setLoading();

    frappe.call({

        method:
            "one_compliance.one_compliance.api.executive_dashboard.get_my_day_summary",

        callback: function(response) {

            if (
                !response ||
                response.exc ||
                !response.message
            ) {

                console.error(
                    "My Day Summary API error:",
                    response
                        ? response.exc
                        : "No response"
                );

                showError();

                return;
            }


            const data =
                response.message;


            if (data.error) {

                console.error(
                    "My Day Summary:",
                    data.error
                );

                showError();

                return;
            }


            console.log(
                "MY DAY SUMMARY DATA:",
                data
            );


            setData(data);

        },

        error: function(error) {

            console.error(
                "Unable to load My Day Summary:",
                error
            );

            showError();

        }

    });

}


/* =====================================================
   INITIAL LOAD
   ===================================================== */

loadMyDaySummary();

})();

