script:
(() => {

    const root = root_element;

    if (!root) {
        return;
    }


    const body = root.querySelector(
        ".capability-body"
    );


    /* =====================================================
       HELPERS
    ===================================================== */

    function escapeHtml(value) {

        if (
            value === null ||
            value === undefined
        ) {
            return "";
        }

        return String(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    function safePercentage(value) {

        const number = Number(value);

        if (!Number.isFinite(number)) {
            return 0;
        }

        return Math.min(
            100,
            Math.max(
                0,
                number
            )
        );
    }


    function getPerformanceLabel(value) {

        const percentage =
            safePercentage(value);

        if (percentage >= 90) {
            return "Excellent";
        }

        if (percentage >= 75) {
            return "Good";
        }

        if (percentage >= 60) {
            return "Needs attention";
        }

        return "Needs improvement";
    }


    /* =====================================================
       METRIC
    ===================================================== */

    function renderMetric(
        label,
        value
    ) {

        const percentage =
            safePercentage(value);

        const performanceLabel =
            getPerformanceLabel(
                percentage
            );

        return `

            <div class="capability-metric">

                <div class="capability-metric-top">

                    <div class="capability-metric-label">
                        ${escapeHtml(label)}
                    </div>

                    <div class="capability-metric-value">
                        ${percentage}%
                    </div>

                </div>


                <div class="capability-progress">

                    <div
                        class="capability-progress-fill"
                        style="width: ${percentage}%"
                    ></div>

                </div>


                <div class="capability-metric-status">
                    ${escapeHtml(
                        performanceLabel
                    )}
                </div>

            </div>

        `;
    }


    /* =====================================================
       IMPROVEMENT ITEM
    ===================================================== */

    function renderImprovement(
        item
    ) {

        return `

            <div class="capability-improvement-item">

                <span class="capability-improvement-dot"></span>

                <span class="capability-improvement-text">
                    ${escapeHtml(item)}
                </span>

            </div>

        `;
    }


    /* =====================================================
       RENDER
    ===================================================== */

    function renderPerformance(data) {

        const metrics =
            data.metrics || {};

        const improvement =
            Array.isArray(
                data.improvement_focus
            )
                ? data.improvement_focus
                : [];


        const taskCompletion =
            safePercentage(
                metrics.task_completion
            );

        const productivity =
            safePercentage(
                metrics.productivity
            );

        const deadlineAdherence =
            safePercentage(
                metrics.deadline_adherence
            );

        const workingHours =
            safePercentage(
                metrics.working_hours
            );


        body.innerHTML = `

            <!-- KEY METRICS -->

            <div class="capability-metrics">

                ${renderMetric(
                    "Task Completion",
                    taskCompletion
                )}

                ${renderMetric(
                    "Productivity",
                    productivity
                )}

                ${renderMetric(
                    "On-Time Rate",
                    deadlineAdherence
                )}

                ${renderMetric(
                    "Working Hours",
                    workingHours
                )}

            </div>


            <!-- IMPROVEMENT -->

            <div class="capability-improvement">

                <div class="capability-improvement-header">

                    <div class="capability-improvement-title">
                        Improvement Focus
                    </div>

                </div>


                <div class="capability-improvement-list">

                    ${
                        improvement.length
                            ? improvement
                                .slice(0, 3)
                                .map(
                                    renderImprovement
                                )
                                .join("")
                            : `
                                <div class="
                                    capability-no-improvement
                                ">
                                    No improvement areas identified.
                                </div>
                            `
                    }

                </div>

            </div>

        `;
    }


    /* =====================================================
       ERROR
    ===================================================== */

    function renderError(
        message
    ) {

        body.innerHTML = `

            <div class="capability-error">

                ${escapeHtml(
                    message ||
                    "Unable to load performance data."
                )}

            </div>

        `;
    }


    /* =====================================================
       LOAD
    ===================================================== */

    function loadPerformance() {

        body.innerHTML = `

            <div class="capability-loading">
                Loading performance...
            </div>

        `;


        frappe.call({

            method:
                "one_compliance.one_compliance.api.executive_dashboard.get_capability_performance",

            callback: function(response) {

                if (
                    !response ||
                    response.exc
                ) {

                    console.error(
                        "Capability Performance API error:",
                        response
                    );

                    renderError(
                        "Unable to load performance data."
                    );

                    return;
                }


                const data =
                    response.message || {};


                if (data.error) {

                    console.error(
                        "Capability Performance error:",
                        data.error
                    );

                    renderError(
                        data.error
                    );

                    return;
                }


                console.log(
                    "CAPABILITY PERFORMANCE DATA:",
                    data
                );


                renderPerformance(
                    data
                );

            },

            error: function(error) {

                console.error(
                    "Unable to load capability performance:",
                    error
                );

                renderError(
                    "Unable to load performance data."
                );

            }

        });

    }


    /* =====================================================
       INITIALIZE
    ===================================================== */

    loadPerformance();

})();

style:
/* =========================================================
   EXECUTIVE DASHBOARD
   CAPABILITY & PERFORMANCE
========================================================= */

.executive-dashboard-block {
    width: 100%;
    box-sizing: border-box;
    font-family: inherit;
}


.capability-performance-block {

    width: 100%;

    background:
        var(--card-bg);

    border:
        1px solid var(--border-color);

    border-radius:
        8px;

    overflow:
        hidden;

    box-sizing:
        border-box;
}


/* =========================================================
   HEADER
========================================================= */

.capability-header {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    padding:
        12px 14px;

    border-bottom:
        1px solid var(--border-color);
}


.capability-title {

    font-size:
        15px;

    font-weight:
        600;

    line-height:
        1.35;

    color:
        var(--text-color);
}


.capability-subtitle {

    margin-top:
        2px;

    font-size:
        11px;

    line-height:
        1.35;

    color:
        var(--text-muted);
}


/* =========================================================
   BODY
========================================================= */

.capability-body {

    width:
        100%;

    box-sizing:
        border-box;
}


/* =========================================================
   METRICS
========================================================= */

.capability-metrics {

    display:
        grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    border-bottom:
        1px solid var(--border-color);
}


.capability-metric {

    min-width:
        0;

    padding:
        11px 13px;

    border-right:
        1px solid var(--border-color);

    box-sizing:
        border-box;
}


.capability-metric:last-child {

    border-right:
        none;
}


/* =========================================================
   METRIC TOP
========================================================= */

.capability-metric-top {

    display:
        flex;

    align-items:
        baseline;

    justify-content:
        space-between;

    gap:
        8px;
}


.capability-metric-label {

    min-width:
        0;

    overflow:
        hidden;

    text-overflow:
        ellipsis;

    white-space:
        nowrap;

    font-size:
        10px;

    font-weight:
        600;

    text-transform:
        uppercase;

    letter-spacing:
        0.02em;

    color:
        var(--text-muted);
}


.capability-metric-value {

    flex-shrink:
        0;

    font-size:
        18px;

    font-weight:
        600;

    line-height:
        1.2;

    color:
        var(--text-color);
}


/* =========================================================
   PROGRESS
========================================================= */

.capability-progress {

    width:
        100%;

    height:
        5px;

    margin-top:
        7px;

    background:
        var(--border-color);

    border-radius:
        10px;

    overflow:
        hidden;
}


.capability-progress-fill {

    height:
        100%;

    background:
        var(--primary-color);

    border-radius:
        10px;

    transition:
        width 0.35s ease;
}


/* =========================================================
   METRIC STATUS
========================================================= */

.capability-metric-status {

    margin-top:
        4px;

    font-size:
        9px;

    line-height:
        1.3;

    color:
        var(--text-muted);

    white-space:
        nowrap;

    overflow:
        hidden;

    text-overflow:
        ellipsis;
}


/* =========================================================
   IMPROVEMENT SECTION
========================================================= */

.capability-improvement {

    padding:
        10px 13px;
}


.capability-improvement-header {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    margin-bottom:
        7px;
}


.capability-improvement-title {

    font-size:
        11px;

    font-weight:
        600;

    color:
        var(--text-color);
}


/* =========================================================
   IMPROVEMENT LIST
========================================================= */

.capability-improvement-list {

    display:
        flex;

    flex-wrap:
        wrap;

    gap:
        6px 14px;
}


.capability-improvement-item {

    display:
        flex;

    align-items:
        center;

    gap:
        6px;

    min-width:
        0;

    font-size:
        10px;

    line-height:
