script:
(() => {

    const root = root_element;

    if (!root) {
        return;
    }


    /* =====================================================
       ELEMENTS
    ===================================================== */

    const weekRange =
        root.querySelector("#week-range");

    const workingHours =
        root.querySelector("#working-hours");

    const effectiveHours =
        root.querySelector("#effective-hours");

    const breakHours =
        root.querySelector("#break-hours");

    const gapHours =
        root.querySelector("#gap-hours");

    const weeklyPercentage =
        root.querySelector("#weekly-percentage");

    const weeklyProgressFill =
        root.querySelector("#weekly-progress-fill");

    const effectiveProgress =
        root.querySelector("#effective-progress");

    const requiredProgress =
        root.querySelector("#required-progress");

    const dailyList =
        root.querySelector("#daily-list");

    const dailyDetailsToggle =
        root.querySelector("#daily-details-toggle");


    /* =====================================================
       FORMAT DURATION
    ===================================================== */

    function formatDuration(hours) {

        const value = parseFloat(hours);

        if (
            isNaN(value) ||
            value <= 0
        ) {
            return "0h 00m";
        }

        const totalMinutes =
            Math.round(value * 60);

        const wholeHours =
            Math.floor(totalMinutes / 60);

        const minutes =
            totalMinutes % 60;

        return (
            `${wholeHours}h ` +
            `${String(minutes).padStart(2, "0")}m`
        );
    }


    /* =====================================================
       FORMAT DATE
    ===================================================== */

    function formatDate(value) {

        if (!value) {
            return "-";
        }

        try {

            return frappe.datetime.str_to_user(
                value
            );

        } catch (error) {

            return value;
        }
    }


    /* =====================================================
       FORMAT WEEK RANGE
    ===================================================== */

    function formatWeekRange(start, end) {

        if (!start || !end) {
            return "-";
        }

        return (
            `${formatDate(start)} – ` +
            `${formatDate(end)}`
        );
    }


    /* =====================================================
       DAILY DETAILS TOGGLE
    ===================================================== */

    if (dailyDetailsToggle && dailyList) {

        dailyDetailsToggle.addEventListener(
            "click",
            function() {

                const isVisible =
                    dailyList.classList.contains(
                        "visible"
                    );


                if (isVisible) {

                    dailyList.classList.remove(
                        "visible"
                    );

                    dailyDetailsToggle.innerHTML = `
                        <span class="toggle-icon">
                            ▸
                        </span>

                        <span class="toggle-text">
                            View details
                        </span>
                    `;

                } else {

                    dailyList.classList.add(
                        "visible"
                    );

                    dailyDetailsToggle.innerHTML = `
                        <span class="toggle-icon">
                            ▾
                        </span>

                        <span class="toggle-text">
                            Hide details
                        </span>
                    `;
                }

            }
        );

    }


    /* =====================================================
       RENDER DAILY DATA
    ===================================================== */

    function renderDailyData(daily) {

        if (!dailyList) {
            return;
        }


        dailyList.innerHTML = "";


        if (
            !Array.isArray(daily) ||
            !daily.length
        ) {

            dailyList.innerHTML = `
                <div class="daily-empty-state">
                    No working-hour data available.
                </div>
            `;

            return;
        }


        daily.forEach(function(day) {

            const working =
                parseFloat(
                    day.working_hours || 0
                );


            const effective =
                parseFloat(
                    day.effective_hours || 0
                );


            const breakTime =
                parseFloat(
                    day.break_hours || 0
                );


            const required =
                parseFloat(
                    day.required_hours || 0
                );


            let percentage = 0;


            if (required > 0) {

                percentage =
                    (
                        effective /
                        required
                    ) * 100;
            }


            percentage =
                Math.min(
                    100,
                    Math.max(
                        0,
                        percentage
                    )
                );


            const hasData =
                working > 0 ||
                effective > 0;


            let statusText =
                "No data";

            let statusClass =
                "no-data";


            if (required <= 0) {

                statusText =
                    hasData
                        ? "Weekend"
                        : "No data";

                statusClass =
                    "no-data";

            } else if (percentage >= 90) {

                statusText =
                    "On track";

                statusClass =
                    "on-track";

            } else if (percentage > 0) {

                statusText =
                    "Partial";

                statusClass =
                    "partial";

            } else {

                statusText =
                    "Not recorded";

                statusClass =
                    "no-data";
            }


            const row =
                document.createElement("div");


            row.className =
                "daily-row" +
                (
                    day.is_today
                        ? " today"
                        : ""
                );


            row.innerHTML = `

                <div class="daily-day">

                    <div class="daily-day-name">
                        ${day.day || "-"}
                    </div>

                    <div class="daily-day-date">
                        ${formatDate(day.date)}
                    </div>

                </div>


                <div class="daily-hours-block">

                    <div class="daily-hours-label">
                        Working
                    </div>

                    <div class="daily-hours-value">
                        ${formatDuration(working)}
                    </div>

                </div>


                <div class="daily-hours-block">

                    <div class="daily-hours-label">
                        Effective
                    </div>

                    <div class="daily-hours-value">
                        ${formatDuration(effective)}
                    </div>

                </div>


                <div class="daily-hours-block">

                    <div class="daily-hours-label">
                        Break
                    </div>

                    <div class="daily-hours-value">
                        ${formatDuration(breakTime)}
                    </div>

                </div>


                <div class="daily-bar-section">

                    <div class="daily-bar-header">

                        <span>
                            Consistency
                        </span>

                        <span>
                            ${
                                required > 0
                                    ? `${percentage.toFixed(0)}%`
                                    : "-"
                            }
                        </span>

                    </div>


                    <div class="daily-bar-track">

                        <div
                            class="daily-bar-fill"
                            style="width: ${percentage}%"
                        ></div>

                    </div>

                </div>


                <div class="daily-status ${statusClass}">
                    ${statusText}
                </div>

            `;


            dailyList.appendChild(row);

        });

    }


    /* =====================================================
       SET DATA
    ===================================================== */

    function setData(data) {

        if (!data) {
            return;
        }


        const totals =
            data.totals || {};


        const totalWorking =
            parseFloat(
                totals.working_hours || 0
            );


        const totalEffective =
            parseFloat(
                totals.effective_hours || 0
            );


        const totalBreak =
            parseFloat(
                totals.break_hours || 0
            );


        const totalRequired =
            parseFloat(
                totals.required_hours || 0
            );


        const totalGap =
            parseFloat(
                totals.gap_hours || 0
            );


        let percentage =
            parseFloat(
                totals.consistency_percentage || 0
            );


        percentage =
            Math.min(
                100,
                Math.max(
                    0,
                    percentage
                )
            );


        /* -------------------------------------------------
           WEEK RANGE
        ------------------------------------------------- */

        if (weekRange) {

            weekRange.textContent =
                formatWeekRange(
                    data.week_start,
                    data.week_end
                );
        }


        /* -------------------------------------------------
           KPI CARDS
        ------------------------------------------------- */

        if (workingHours) {

            workingHours.textContent =
                formatDuration(
                    totalWorking
                );
        }


        if (effectiveHours) {

            effectiveHours.textContent =
                formatDuration(
                    totalEffective
                );
        }


        if (breakHours) {

            breakHours.textContent =
                formatDuration(
                    totalBreak
                );
        }


        if (gapHours) {

            gapHours.textContent =
                formatDuration(
                    totalGap
                );
        }


        /* -------------------------------------------------
           WEEKLY PROGRESS
        ------------------------------------------------- */

        if (weeklyPercentage) {

            weeklyPercentage.textContent =
                `${percentage.toFixed(0)}%`;
        }


        if (weeklyProgressFill) {

            weeklyProgressFill.style.width =
                `${percentage}%`;
        }


        if (effectiveProgress) {

            effectiveProgress.textContent =
                formatDuration(
                    totalEffective
                );
        }


        if (requiredProgress) {

            requiredProgress.textContent =
                formatDuration(
                    totalRequired
                );
        }


        /* -------------------------------------------------
           DAILY DATA
        ------------------------------------------------- */

        renderDailyData(
            data.daily || []
        );

    }


    /* =====================================================
       ERROR STATE
    ===================================================== */

    function showError() {

        const elements = [

            weekRange,
            workingHours,
            effectiveHours,
            breakHours,
            gapHours,
            weeklyPercentage,
            effectiveProgress,
            requiredProgress

        ];


        elements.forEach(
            function(element) {

                if (element) {

                    element.textContent =
                        "-";
                }

            }
        );


        if (weeklyProgressFill) {

            weeklyProgressFill.style.width =
                "0%";
        }


        if (dailyList) {

            dailyList.innerHTML = `
                <div class="daily-empty-state">
                    Unable to load working-hour data.
                </div>
            `;

        }

    }


    /* =====================================================
       LOAD WEEKLY ANALYSIS
    ===================================================== */

    function loadWeeklyAnalysis() {

        frappe.call({

            method:
                "one_compliance.one_compliance.api.executive_dashboard.get_weekly_working_hours_analysis",

            callback: function(response) {

                if (
                    !response ||
                    response.exc ||
                    !response.message
                ) {

                    console.error(
                        "Weekly Working Hours API error:",
                        response
                            ? response.exc
                            : "No response"
                    );

                    showError();

                    return;
                }


                const data =
                    response.message;


                if (data.error) {

                    console.error(
                        "Weekly Working Hours:",
                        data.error
                    );

                    showError();

                    return;
                }


                console.log(
                    "WEEKLY WORKING HOURS DATA:",
                    data
                );


                setData(data);

            },


            error: function(error) {

                console.error(
                    "Unable to load weekly working hours:",
                    error
                );

                showError();

            }

        });

    }


    /* =====================================================
       INITIAL LOAD
    ===================================================== */

    loadWeeklyAnalysis();

})();

style:
.executive-dashboard-block {
    width: 100%;
    font-family: inherit;
    box-sizing: border-box;
}

/* =========================================================
   WORKING HOURS ANALYSIS - GRAY BACKGROUND
========================================================= */

.working-hours-analysis {
    width: 100%;
    padding: 16px;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    box-sizing: border-box;
}

/* =========================================================
   HEADER
========================================================= */

.working-hours-analysis .block-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 14px;
}


.working-hours-analysis .block-title {
    font-size: 19px;
    font-weight: 650;
    line-height: 1.4;
    letter-spacing: -0.2px;
    color: var(--text-color);
}


.working-hours-analysis .block-subtitle {
    margin-top: 4px;
    font-size: 12px;
    line-height: 1.4;
    color: var(--text-muted);
}


.working-hours-analysis .week-range {
    padding: 6px 10px;
    border: 1px solid #dbe3ec;
    border-radius: 7px;
    background: #ffffff;
    font-size: 11px;
    font-weight: 550;
    color: var(--text-muted);
    white-space: nowrap;
}


/* =========================================================
   KPI GRID
========================================================= */

.working-hours-analysis .hours-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    margin-bottom: 14px;
}


/* =========================================================
   KPI CARD
========================================================= */

.working-hours-analysis .hours-card {
    position: relative;
    min-height: 82px;
    padding: 11px 13px;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    background: #ffffff;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: center;
    overflow: hidden;
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease,
        border-color 0.15s ease;
}


.working-hours-analysis .hours-card::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
}


.working-hours-analysis .hours-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 3px 10px rgba(15, 23, 42, 0.07);
    border-color: #cbd5e1;
}


/* =========================================================
   KPI LABEL
========================================================= */

.working-hours-analysis .hours-label {
    margin-bottom: 3px;
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.25px;
    color: var(--text-muted);
}


/* =========================================================
   KPI VALUE
========================================================= */

.working-hours-analysis .hours-value {
    font-size: 19px;
    font-weight: 700;
    line-height: 1.2;
    color: var(--text-color);
    white-space: nowrap;
}


/* =========================================================
   KPI DESCRIPTION
========================================================= */

.working-hours-analysis .hours-description {
    margin-top: 3px;
    font-size: 9px;
    line-height: 1.3;
    color: var(--text-muted);
}


/* =========================================================
   WORKING HOURS
========================================================= */

.working-hours-analysis .working-card {
    background: linear-gradient(
        135deg,
        #eff6ff 0%,
        #ffffff 100%
    );
}


.working-hours-analysis .working-card::before {
    background: #3b82f6;
}


.working-hours-analysis .working-card .hours-value {
    color: #2563eb;
}


/* =========================================================
   EFFECTIVE HOURS
========================================================= */

.working-hours-analysis .effective-card {
    background: linear-gradient(
        135deg,
        #ecfdf5 0%,
        #ffffff 100%
