/* =========================================================
   BREAK HOURS
========================================================= */

.working-hours-analysis .break-card {
    background: linear-gradient(
        135deg,
        #fffbeb 0%,
        #ffffff 100%
    );
}


.working-hours-analysis .break-card::before {
    background: #f59e0b;
}


.working-hours-analysis .break-card .hours-value {
    color: #d97706;
}


/* =========================================================
   GAP HOURS
