script:
(() => {
    const root = root_element;

    if (!root) {
        return;
    }

    /* =====================================================
       STATE
    ====================================================== */

    let allTasks = [];
    let currentFilter = "all";


    /* =====================================================
       ELEMENTS
    ====================================================== */

    const taskList =
        root.querySelector("#task-list");

    const emptyState =
        root.querySelector("#task-empty-state");

    const loadingState =
        root.querySelector("#task-loading-state");

    const totalCount =
        root.querySelector("#task-total-count");

    const allCount =
        root.querySelector("#task-all-count");

    const openCount =
        root.querySelector("#task-open-count");

    const workingCount =
        root.querySelector("#task-working-count");

    const completedCount =
        root.querySelector("#task-completed-count");

    const pendingCount =
        root.querySelector("#task-pending-count");

    const footerCompleted =
        root.querySelector("#task-footer-completed");

    const dueTodayCount =
        root.querySelector("#task-due-today-count");

    const filterCount =
        root.querySelector("#task-filter-count");

    const filterButtons =
        root.querySelectorAll(
            ".task-filter-button"
        );

    const summaryCards =
        root.querySelectorAll(
            ".task-summary-card"
        );


    /* =====================================================
       DATE HELPERS
    ====================================================== */

    function getTodayString() {
        return frappe.datetime.get_today();
    }


    function normalizeDate(value) {
        if (!value) {
            return null;
        }

        return String(value).substring(0, 10);
    }


    function formatDate(value) {
        if (!value) {
            return "-";
        }

        try {
            return frappe.datetime.str_to_user(value);
        } catch (error) {
            return value;
        }
    }


    /* =====================================================
       STATUS
    ====================================================== */

    function normalizeStatus(status) {
        if (!status) {
            return "";
        }

        return String(status)
            .trim()
            .toLowerCase();
    }


    function isOpen(task) {
        return normalizeStatus(task.status) === "open";
    }


    function isWorking(task) {
        const status =
            normalizeStatus(task.status);

        return (
            status === "working" ||
            status === "in progress" ||
            status === "in-progress"
        );
    }


    function isCompleted(task) {
        return (
            normalizeStatus(task.status) ===
            "completed"
        );
    }


    /* =====================================================
       PRIORITY
    ====================================================== */

    function getPriorityClass(priority) {

        if (!priority) {
            return "priority-none";
        }

        const value =
            String(priority)
                .trim()
                .toLowerCase();

        if (value === "urgent") {
            return "priority-urgent";
        }

        if (value === "high") {
            return "priority-high";
        }

        if (value === "medium") {
            return "priority-medium";
        }

        if (value === "low") {
            return "priority-low";
        }

        return "priority-none";
    }


    /* =====================================================
       STATUS CLASS
    ====================================================== */

    function getStatusClass(status) {

        const value =
            normalizeStatus(status);

        if (value === "completed") {
            return "status-completed";
        }

        if (
            value === "working" ||
            value === "in progress" ||
            value === "in-progress"
        ) {
            return "status-working";
        }

        if (value === "open") {
            return "status-open";
        }

        if (value === "cancelled") {
            return "status-cancelled";
        }

        return "status-default";
    }


    /* =====================================================
       DEADLINE
    ====================================================== */

    function getDeadlineInfo(task) {

        const deadline =
            normalizeDate(
                task.exp_end_date
            );

        if (!deadline) {
            return {
                text: "-",
                className: "deadline-none",
                label: ""
            };
        }

        const today =
            getTodayString();

        if (isCompleted(task)) {
            return {
                text: formatDate(
                    task.exp_end_date
                ),
                className: "deadline-none",
                label: "Completed"
            };
        }

        if (deadline < today) {
            return {
                text: formatDate(
                    task.exp_end_date
                ),
                className: "deadline-overdue",
                label: "Overdue"
            };
        }

        if (deadline === today) {
            return {
                text: formatDate(
                    task.exp_end_date
                ),
                className: "deadline-today",
                label: "Due Today"
            };
        }

        return {
            text: formatDate(
                task.exp_end_date
            ),
            className: "deadline-upcoming",
            label: ""
        };
    }


    /* =====================================================
       FILTER LOGIC
    ====================================================== */

    function filterTasks(filter) {

        if (filter === "all") {
            return allTasks;
        }

        if (filter === "today") {

            const today =
                getTodayString();

            return allTasks.filter(
                function(task) {

                    return (
                        normalizeDate(
                            task.exp_end_date
                        ) === today
                    );

                }
            );
        }

        if (filter === "open") {

            return allTasks.filter(
                function(task) {
                    return isOpen(task);
                }
            );
        }

        if (filter === "working") {

            return allTasks.filter(
                function(task) {
                    return isWorking(task);
                }
            );
        }

        if (filter === "completed") {

            return allTasks.filter(
                function(task) {
                    return isCompleted(task);
                }
            );
        }

        return allTasks;
    }


    /* =====================================================
       SUMMARY
    ====================================================== */

    function updateSummary() {

        const total =
            allTasks.length;

        const open =
            allTasks.filter(
                function(task) {
                    return isOpen(task);
                }
            ).length;

        const working =
            allTasks.filter(
                function(task) {
                    return isWorking(task);
                }
            ).length;

        const completed =
            allTasks.filter(
                function(task) {
                    return isCompleted(task);
                }
            ).length;

        const today =
            getTodayString();

        const dueToday =
            allTasks.filter(
                function(task) {

                    return (
                        !isCompleted(task) &&
                        normalizeDate(
                            task.exp_end_date
                        ) === today
                    );

                }
            ).length;

        const pending =
            allTasks.filter(
                function(task) {
                    return !isCompleted(task);
                }
            ).length;


        if (totalCount) {
            totalCount.textContent = total;
        }

        if (allCount) {
            allCount.textContent = total;
        }

        if (openCount) {
            openCount.textContent = open;
        }

        if (workingCount) {
            workingCount.textContent = working;
        }

        if (completedCount) {
            completedCount.textContent = completed;
        }

        if (pendingCount) {
            pendingCount.textContent = pending;
        }

        if (footerCompleted) {
            footerCompleted.textContent = completed;
        }

        if (dueTodayCount) {
            dueTodayCount.textContent = dueToday;
        }
    }


    /* =====================================================
       ACTIVE FILTER
    ====================================================== */

    function updateActiveFilter() {

        filterButtons.forEach(
            function(button) {

                button.classList.toggle(
                    "active",
                    button.dataset.filter ===
                    currentFilter
                );

            }
        );

        summaryCards.forEach(
            function(card) {

                card.classList.toggle(
                    "active",
                    card.dataset.filter ===
                    currentFilter
                );

            }
        );
    }


    /* =====================================================
       OPEN TASK
    ====================================================== */

    function openTask(task) {

        if (!task) {
            return;
        }

        const taskName =
            task.name ||
            task.task_name;

        if (!taskName) {
            return;
        }

        frappe.set_route(
            "Form",
            "Task",
            taskName
        );
    }


    /* =====================================================
       TASK ROW
    ====================================================== */

    function createTaskRow(task) {

        const subject =
            task.subject ||
            task.name ||
            "-";

        const priority =
            task.priority ||
            "-";

        const status =
            task.status ||
            "-";

        const priorityClass =
            getPriorityClass(
                task.priority
            );

        const statusClass =
            getStatusClass(
                task.status
            );

        const deadline =
            getDeadlineInfo(task);

        const project =
            task.project_name ||
            task.project ||
            "";


        const row =
            document.createElement(
                "div"
            );

        row.className =
            "task-row";

        row.setAttribute(
            "role",
            "button"
        );

        row.setAttribute(
            "tabindex",
            "0"
        );

        row.title =
            "Open Task";


        row.innerHTML = `

            <div class="task-main">

                <div class="task-subject">

                    ${frappe.utils.escape_html(
                        subject
                    )}

                </div>

                ${
                    project
                        ? `
                            <div class="task-project">
                                ${frappe.utils.escape_html(
                                    project
                                )}
                            </div>
                          `
                        : ""
                }

            </div>


            <div class="task-column">

                <span
                    class="
                        task-priority
                        ${priorityClass}
                    "
                >
                    ${frappe.utils.escape_html(
                        priority
                    )}
                </span>

            </div>


            <div
                class="
                    task-column
                    task-deadline
                    ${deadline.className}
                "
            >

                ${
                    deadline.label
                        ? `
                            <span class="deadline-label">
                                ${frappe.utils.escape_html(
                                    deadline.label
                                )}
                            </span>
                          `
                        : ""
                }

                <span>
                    ${frappe.utils.escape_html(
                        deadline.text
                    )}
                </span>

            </div>


            <div class="task-column">

                <span
                    class="
                        task-status
                        ${statusClass}
                    "
                >
                    ${frappe.utils.escape_html(
                        status
                    )}
                </span>

            </div>

        `;


        /* =================================================
           CLICK
        ================================================= */

        row.addEventListener(
            "click",
            function() {
                openTask(task);
            }
        );


        /* =================================================
           KEYBOARD ACCESS
        ================================================= */

        row.addEventListener(
            "keydown",
            function(event) {

                if (
                    event.key === "Enter" ||
                    event.key === " "
                ) {

                    event.preventDefault();

                    openTask(task);
                }

            }
        );


        return row;
    }


    /* =====================================================
       RENDER
    ====================================================== */

    function renderTasks() {

        if (!taskList) {
            return;
        }

        taskList.innerHTML = "";

        const filteredTasks =
            filterTasks(
                currentFilter
            );


        if (filterCount) {

            filterCount.textContent =
                `${filteredTasks.length} ${
                    filteredTasks.length === 1
                        ? "task"
                        : "tasks"
                }`;
        }


        if (!filteredTasks.length) {

            if (emptyState) {
                emptyState.style.display =
                    "flex";
            }

            return;
        }


        if (emptyState) {
            emptyState.style.display =
                "none";
        }


        filteredTasks.forEach(
            function(task) {

                taskList.appendChild(
                    createTaskRow(task)
                );

            }
        );
    }


    /* =====================================================
       LOADING
    ====================================================== */

    function showLoading() {

        if (loadingState) {
            loadingState.style.display =
                "block";
        }

        if (emptyState) {
            emptyState.style.display =
                "none";
        }

        if (taskList) {
            taskList.innerHTML = "";
        }
    }


    /* =====================================================
       ERROR
    ====================================================== */

    function showError() {

        if (loadingState) {
            loadingState.style.display =
                "none";
        }

        if (emptyState) {
            emptyState.style.display =
                "flex";
        }

        if (taskList) {
            taskList.innerHTML = "";
        }

        if (filterCount) {
            filterCount.textContent =
                "Unable to load tasks";
        }
    }


    /* =====================================================
       FILTER EVENTS
    ====================================================== */

    filterButtons.forEach(
        function(button) {

            button.addEventListener(
                "click",
                function() {

                    currentFilter =
                        button.dataset.filter ||
                        "all";

                    updateActiveFilter();

                    renderTasks();

                }
            );

        }
    );


    summaryCards.forEach(
        function(card) {

            card.addEventListener(
                "click",
                function() {

                    currentFilter =
                        card.dataset.filter ||
                        "all";

                    updateActiveFilter();

                    renderTasks();

                }
            );

        }
    );


    /* =====================================================
       LOAD TASKS
    ====================================================== */

    function loadTasks() {

        showLoading();

        frappe.call({

            method:
                "one_compliance.one_compliance.api.executive_dashboard.get_my_tasks",

            callback:
                function(response) {

                    if (
                        !response ||
                        response.exc ||
                        !response.message
                    ) {

                        console.error(
                            "Task Management API error:",
                            response
                        );

                        allTasks = [];

                        updateSummary();

                        showError();

                        return;
                    }


                    const data =
                        response.message;


                    if (data.error) {

                        console.error(
                            "Task Management error:",
                            data.error
                        );

                        allTasks = [];

                        updateSummary();

                        showError();

                        return;
                    }


                    allTasks =
                        Array.isArray(
                            data.tasks
                        )
                            ? data.tasks
                            : [];


                    console.log(
                        "TASK MANAGEMENT DATA:",
                        data
                    );


                    updateSummary();

                    updateActiveFilter();

                    renderTasks();

                },

            error:
                function(error) {

                    console.error(
                        "Unable to load tasks:",
                        error
                    );

                    allTasks = [];

                    updateSummary();

                    showError();

                },

            always:
                function() {

                    if (loadingState) {

                        loadingState.style.display =
                            "none";

                    }

                }

        });
    }


    /* =====================================================
       INITIALIZE
    ====================================================== */

    updateActiveFilter();

    loadTasks();

})();

style:
/* =========================================================
   EXECUTIVE DASHBOARD
   TASK MANAGEMENT
========================================================= */

.executive-dashboard-block {
    width: 100%;
    font-family: inherit;
    box-sizing: border-box;
}

.task-management-dashboard {
    width: 100%;
    padding: 2px 0;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
========================================================= */

.task-management-dashboard .task-block-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 10px;
}

.task-management-dashboard .task-block-title {
    font-size: 16px;
    font-weight: 600;
    line-height: 1.3;
    color: var(--text-color);
}

.task-management-dashboard .task-block-subtitle {
    margin-top: 2px;
    font-size: 11px;
    line-height: 1.3;
    color: var(--text-muted);
}

.task-management-dashboard .task-block-total {
    display: flex;
    align-items: baseline;
    gap: 4px;
    flex-shrink: 0;
}

.task-management-dashboard #task-total-count {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-color);
}

.task-management-dashboard .task-total-label {
    font-size: 10px;
    color: var(--text-muted);
}


/* =========================================================
   SUMMARY GRID
========================================================= */

.task-management-dashboard .task-summary-grid {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 8px;

    margin-bottom: 9px;
}


/* =========================================================
   SUMMARY CARD
========================================================= */

.task-management-dashboard .task-summary-card {

    position: relative;

    min-width: 0;
    min-height: 70px;

    padding: 10px 12px 10px 14px;

    border: 1px solid var(--border-color);

    border-radius: 7px;

    background: var(--card-bg);

    display: flex;
    flex-direction: column;
    justify-content: center;

    box-sizing: border-box;

    cursor: pointer;

    overflow: hidden;

    transition:
        background 0.12s ease,
        border-color 0.12s ease,
        box-shadow 0.12s ease,
        transform 0.12s ease;
}


/* =========================================================
   SUBTLE LEFT ACCENT
========================================================= */

.task-management-dashboard
.task-summary-card::before {

    content: "";

    position: absolute;

    left: 0;
    top: 0;
    bottom: 0;

    width: 3px;

    background: var(--border-color);
}


/* ALL */

.task-management-dashboard
.task-summary-card:nth-child(1) {

    background:
        linear-gradient(
            135deg,
            #f8fafc 0%,
            #ffffff 100%
        );
}

.task-management-dashboard
.task-summary-card:nth-child(1)::before {

    background: #64748b;
}


/* OPEN */

.task-management-dashboard
.task-summary-card:nth-child(2) {

    background:
        linear-gradient(
            135deg,
            #eff6ff 0%,
            #ffffff 100%
        );
}

.task-management-dashboard
.task-summary-card:nth-child(2)::before {

    background: #3b82f6;
}


/* WORKING */

.task-management-dashboard
.task-summary-card:nth-child(3) {

    background:
        linear-gradient(
            135deg,
            #f0fdf4 0%,
            #ffffff 100%
        );
}

.task-management-dashboard
.task-summary-card:nth-child(3)::before {

    background: #22c55e;
}


/* COMPLETED */

.task-management-dashboard
.task-summary-card:nth-child(4) {

    background:
        linear-gradient(
            135deg,
            #f8fafc 0%,
            #ffffff 100%
        );
}

.task-management-dashboard
.task-summary-card:nth-child(4)::before {

    background: #10b981;
}


/* =========================================================
   SUMMARY HOVER
========================================================= */

.task-management-dashboard
.task-summary-card:hover {

    transform: translateY(-1px);

    box-shadow:
        0 2px 7px rgba(15, 23, 42, 0.06);

    border-color:
        #cbd5e1;
}


/* =========================================================
   SUMMARY ACTIVE
========================================================= */

.task-management-dashboard
.task-summary-card.active {

    border-color:
        var(--primary-color);

    box-shadow:
        0 1px 5px rgba(15, 23, 42, 0.05);
}


/* Keep active card accent subtle */

.task-management-dashboard
.task-summary-card.active::before {

    width: 3px;

    background:
        var(--primary-color);
}


/* =========================================================
   SUMMARY TOP
========================================================= */

.task-management-dashboard .task-summary-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 6px;

    min-width: 0;

    margin-bottom: 2px;
}

.task-management-dashboard .task-summary-label {

    font-size: 10px;

    font-weight: 600;

    color: var(--text-muted);

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


/* =========================================================
   SUMMARY DOT
========================================================= */

.task-management-dashboard .task-summary-dot {

    width: 5px;
    height: 5px;

    flex-shrink: 0;

    border-radius: 50%;

    background: #94a3b8;
}


/* Individual dots */

.task-management-dashboard
.task-summary-card:nth-child(1)
.task-summary-dot {

    background: #64748b;
}

.task-management-dashboard
.task-summary-card:nth-child(2)
.task-summary-dot {

    background: #3b82f6;
}

.task-management-dashboard
.task-summary-card:nth-child(3)
.task-summary-dot {

    background: #22c55e;
}

.task-management-dashboard
.task-summary-card:nth-child(4)
.task-summary-dot {

    background: #10b981;
}


/* =========================================================
   SUMMARY VALUE
========================================================= */

.task-management-dashboard .task-summary-value {

    font-size: 20px;

    font-weight: 700;

    line-height: 1.2;

    color: var(--text-color);

    white-space: nowrap;
}


/* =========================================================
   SUMMARY DESCRIPTION
========================================================= */

.task-management-dashboard .task-summary-description {

    margin-top: 2px;

    font-size: 9px;

    line-height: 1.2;

    color: var(--text-muted);
}


/* =========================================================
   FILTER SECTION
========================================================= */

.task-management-dashboard .task-filter-section {

    width: 100%;

    padding: 8px 10px;

    border: 1px solid var(--border-color);

    border-radius: 7px;

    background: var(--card-bg);

    box-sizing: border-box;

    margin-bottom: 9px;
}

.task-management-dashboard .task-filter-left {

    display: flex;

    align-items: center;

    gap: 8px;

    flex-wrap: wrap;
}

.task-management-dashboard .task-filter-label {

    font-size: 10px;

    font-weight: 600;

    color: var(--text-muted);

    white-space: nowrap;
}

.task-management-dashboard .task-filter-buttons {

    display: flex;

    align-items: center;

    gap: 5px;

    flex-wrap: wrap;
}


/* =========================================================
   FILTER BUTTON
========================================================= */

.task-management-dashboard .task-filter-button {

    appearance: none;

    border: 1px solid var(--border-color);

    border-radius: 5px;

    background: var(--bg-color);

    color: var(--text-muted);

    padding: 4px 9px;

    font-family: inherit;

    font-size: 10px;

    font-weight: 500;

    line-height: 1.2;

    cursor: pointer;

    transition:
        background 0.12s ease,
        border-color 0.12s ease,
        color 0.12s ease;
}

.task-management-dashboard
.task-filter-button:hover {

    border-color:
        var(--primary-color);

    color:
        var(--text-color);
}

.task-management-dashboard
.task-filter-button.active {

    background:
        var(--control-bg);

    border-color:
        var(--primary-color);

    color:
        var(--text-color);

    font-weight: 600;
}


/* =========================================================
   TASK LIST CONTAINER
========================================================= */

.task-management-dashboard .task-list-container {

    width: 100%;

    border: 1px solid var(--border-color);

    border-radius: 7px;

    background: var(--card-bg);

    overflow: hidden;

    box-sizing: border-box;
}


/* =========================================================
   LIST HEADER
========================================================= */

.task-management-dashboard .task-list-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 10px;

    padding: 9px 12px;

    border-bottom:
        1px solid var(--border-color);
}

.task-management-dashboard .task-list-title {

    font-size: 11px;

    font-weight: 600;

    color: var(--text-color);
}

.task-management-dashboard .task-list-subtitle {

    margin-top: 2px;

    font-size: 9px;

    color: var(--text-muted);
}

.task-management-dashboard .task-list-count {

    font-size: 9px;

    color: var(--text-muted);

    white-space: nowrap;
}


/* =========================================================
   TABLE HEADER
========================================================= */

.task-management-dashboard .task-table-header {

    display: grid;

    grid-template-columns:
        minmax(0, 2.5fr)
        minmax(85px, 0.8fr)
        minmax(105px, 0.9fr)
        minmax(95px, 0.8fr);

    gap: 10px;

    padding: 6px 12px;

    border-bottom:
        1px solid var(--border-color);

    background:
        var(--bg-light-gray);
}

.task-management-dashboard
.task-table-header > div {

    font-size: 9px;

    font-weight: 600;

    color: var(--text-muted);

    text-transform: uppercase;

    letter-spacing: 0.02em;
}


/* =========================================================
   TASK ROW
========================================================= */

.task-management-dashboard .task-row {

    display: grid;

    grid-template-columns:
        minmax(0, 2.5fr)
        minmax(85px, 0.8fr)
        minmax(105px, 0.9fr)
        minmax(95px, 0.8fr);

    gap: 10px;

    align-items: center;

    padding: 8px 12px;

    min-height: 48px;

    border-bottom:
        1px solid var(--border-color);

    background:
        var(--card-bg);

    cursor: pointer;

    outline: none;

    transition:
        background 0.12s ease,
        box-shadow 0.12s ease;
}

.task-management-dashboard
.task-row:last-child {

    border-bottom: none;
}

.task-management-dashboard
.task-row:hover {

    background:
        var(--control-bg);
}

.task-management-dashboard
.task-row:focus-visible {

    box-shadow:
        inset 0 0 0 1px var(--primary-color);
}


/* =========================================================
   TASK MAIN
========================================================= */

.task-management-dashboard .task-main {

    min-width: 0;
}

.task-management-dashboard .task-subject {

    font-size: 11px;

    font-weight: 500;

    line-height: 1.3;

    color: var(--text-color);

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.task-management-dashboard .task-project {

    margin-top: 2px;

    font-size: 9px;

    line-height: 1.2;

    color: var(--text-muted);

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


/* =========================================================
   TASK COLUMN
========================================================= */

.task-management-dashboard .task-column {

    min-width: 0;

    font-size: 10px;

    color: var(--text-color);
}


/* =========================================================
   PRIORITY
========================================================= */

.task-management-dashboard .task-priority {

    display: inline-flex;

    align-items: center;

    padding: 3px 6px;

    border-radius: 4px;

    font-size: 9px;

    font-weight: 600;

    white-space: nowrap;

    border: 1px solid var(--border-color);
}


/* =========================================================
   PRIORITY STATES
========================================================= */

.task-management-dashboard .priority-urgent {

    color: var(--text-color);

    background:
        var(--control-bg);

    border-color:
        var(--text-color);
}

.task-management-dashboard .priority-high {

    color: var(--text-color);

    background:
        var(--control-bg);

    border-color:
        var(--border-color);
}

.task-management-dashboard
.priority-medium,
.task-management-dashboard
.priority-low,
.task-management-dashboard
.priority-none {

    color: var(--text-muted);

    background:
        var(--bg-color);
}


/* =========================================================
   STATUS
========================================================= */

.task-management-dashboard .task-status {

    display: inline-flex;

    align-items: center;

    padding: 3px 6px;

    border-radius: 4px;

    font-size: 9px;

    font-weight: 500;

    white-space: nowrap;

    border: 1px solid var(--border-color);
}


/* =========================================================
   STATUS STATES
========================================================= */

.task-management-dashboard
.status-completed {

    background:
        #f0fdf4;

    color:
        #15803d;

    border-color:
        #bbf7d0;
}

.task-management-dashboard
.status-working {

    background:
        #eff6ff;

    color:
        #2563eb;

    border-color:
        #bfdbfe;
}

.task-management-dashboard
.status-open {

    background:
        #f8fafc;

    color:
        #475569;

    border-color:
        #e2e8f0;
}

.task-management-dashboard
.status-cancelled,
.task-management-dashboard
.status-default {

    color:
        var(--text-muted);

    background:
        var(--bg-color);
}


/* =========================================================
   DEADLINE
========================================================= */

.task-management-dashboard .task-deadline {

    display: flex;

    flex-direction: column;

    gap: 1px;

    line-height: 1.2;
}

.task-management-dashboard .deadline-label {

    font-size: 8px;

    font-weight: 600;

    text-transform: uppercase;

    letter-spacing: 0.02em;
}

.task-management-dashboard .deadline-overdue {

    font-weight: 600;

    color: #dc2626;
}

.task-management-dashboard .deadline-today {

    font-weight: 600;

    color: #d97706;
}

.task-management-dashboard .deadline-upcoming {

    color: var(--text-color);
}

.task-management-dashboard .deadline-none {

    color: var(--text-muted);
}


/* =========================================================
   EMPTY STATE
========================================================= */

.task-management-dashboard .task-empty-state {

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    min-height: 90px;

    padding: 16px;

    text-align: center;
}

.task-management-dashboard .task-empty-icon {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 22px;

    height: 22px;

    margin-bottom: 5px;

    border-radius: 50%;

    background: #f0fdf4;

    color: #16a34a;

    font-size: 12px;

    font-weight: 700;
}

.task-management-dashboard .task-empty-title {

    font-size: 11px;

    font-weight: 600;

    color: var(--text-color);
}

.task-management-dashboard .task-empty-description {

    margin-top: 3px;

    font-size: 9px;

    line-height: 1.3;

    color: var(--text-muted);
}


/* =========================================================
   LOADING
========================================================= */

.task-management-dashboard .task-loading-state {

    padding: 14px;

    text-align: center;

    font-size: 10px;

    color: var(--text-muted);
}

.task-management-dashboard .task-loading-spinner {

    display: inline-block;

    width: 10px;

    height: 10px;

    margin-right: 5px;

    border: 1px solid var(--border-color);

    border-top-color:
        var(--primary-color);

    border-radius: 50%;

    vertical-align: -2px;

    animation:
        task-spin 0.7s linear infinite;
}

@keyframes task-spin {

    to {
        transform: rotate(360deg);
    }
}


/* =========================================================
   FOOTER
========================================================= */

.task-management-dashboard .task-block-footer {

    display: flex;

    align-items: center;

    gap: 18px;

    padding: 7px 2px 0;

    color: var(--text-muted);
}

.task-management-dashboard .task-footer-item {

    display: flex;

    align-items: center;

    gap: 5px;
}

.task-management-dashboard .task-footer-label {

    font-size: 9px;
}

.task-management-dashboard .task-footer-value {

    font-size: 10px;

    font-weight: 600;

    color: var(--text-color);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1000px) {

    .task-management-dashboard
    .task-summary-grid {

        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

    .task-management-dashboard
    .task-table-header,
    .task-management-dashboard
    .task-row {

        grid-template-columns:
            minmax(0, 2fr)
            minmax(80px, 0.8fr)
            minmax(100px, 0.9fr)
            minmax(90px, 0.8fr);
    }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 600px) {

    .task-management-dashboard {

        padding: 2px 0;
    }


    /* HEADER */

    .task-management-dashboard
    .task-block-header {

        align-items: flex-start;

        flex-direction: column;

        gap: 5px;

        margin-bottom: 9px;
    }


    .task-management-dashboard
    .task-block-title {

        font-size: 15px;
    }


    .task-management-dashboard
    .task-block-subtitle {

        font-size: 10px;
    }


    .task-management-dashboard
    .task-block-total {

        align-self: flex-end;
    }


    /* SUMMARY */

    .task-management-dashboard
    .task-summary-grid {

        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap: 6px;

        margin-bottom: 8px;
    }


    .task-management-dashboard
    .task-summary-card {

        min-height: 66px;

        padding: 9px 10px 9px 12px;
    }


    .task-management-dashboard
    .task-summary-value {

        font-size: 18px;
    }


    .task-management-dashboard
    .task-summary-description {

        display: none;
    }


    /* FILTER */

    .task-management-dashboard
    .task-filter-section {

        padding: 7px 8px;
    }


    .task-management-dashboard
    .task-filter-left {

        align-items: flex-start;

        flex-direction: column;

        gap: 5px;
    }


    .task-management-dashboard
    .task-filter-buttons {

        width: 100%;

        gap: 4px;
    }


    .task-management-dashboard
    .task-filter-button {

        padding: 4px 8px;

        font-size: 9px;
    }


    /* LIST HEADER */

    .task-management-dashboard
    .task-list-header {

        padding: 8px 10px;
    }


    /* TABLE */

    .task-management-dashboard
    .task-table-header {

        display: none;
    }


    /* ROW */

    .task-management-dashboard
    .task-row {

        grid-template-columns:
            1fr;

        gap: 6px;

        padding: 10px 12px;

        min-height: auto;
    }


    .task-management-dashboard
    .task-column {

        display: flex;

        align-items: center;

        gap: 6px;
    }


    .task-management-dashboard
    .task-column::before {

        min-width: 58px;

        font-size: 9px;

        font-weight: 600;

        color: var(--text-muted);
    }


    .task-management-dashboard
    .task-row
    .task-column:nth-child(2)::before {

        content: "Priority";
    }


    .task-management-dashboard
    .task-row
    .task-column:nth-child(3)::before {

        content: "Deadline";
    }


    .task-management-dashboard
    .task-row
    .task-column:nth-child(4)::before {

        content: "Status";
    }


    .task-management-dashboard
    .task-subject {

        white-space: normal;

        overflow: visible;

        text-overflow: initial;
    }


    /* FOOTER */

    .task-management-dashboard
    .task-block-footer {

        gap: 12px;

        flex-wrap: wrap;
    }
}
